import type { MetadataRoute } from 'next';

/**
 * Web app manifest (served at /manifest.webmanifest): lets phones install Kiln to the home screen
 * with its own name, icon and colours. Icons are generated by `npm run icons`.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: 'Kiln: deploy any Git repo',
    short_name: 'Kiln',
    description: 'Local-first deployment platform: paste a Git URL, watch it build live, get a URL.',
    start_url: '/deployments',
    scope: '/',
    display: 'standalone',
    orientation: 'portrait',
    background_color: '#0c0a09',
    theme_color: '#0c0a09',
    categories: ['developer', 'productivity', 'utilities'],
    icons: [
      { src: '/icons/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
      { src: '/icons/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
      { src: '/icons/maskable-192.png', sizes: '192x192', type: 'image/png', purpose: 'maskable' },
      { src: '/icons/maskable-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
    ],
    shortcuts: [
      { name: 'New deployment', short_name: 'Deploy', url: '/new', icons: [{ src: '/icons/icon-192.png', sizes: '192x192' }] },
      { name: 'Deployments', url: '/deployments', icons: [{ src: '/icons/icon-192.png', sizes: '192x192' }] },
    ],
  };
}
